import loggingimport subprocessfrom datetime import datetimefrom pathlib import Pathfrom .pathutil import resolve_pattern_BASE_NAME = 'example'def _get_logger(root: Path) -> logging.Logger:    log_dir = root / 'logs'    log_dir.mkdir(exist_ok=True)    logger = logging.getLogger('convert')    if not logger.handlers:        handler = logging.FileHandler(log_dir / 'convert.log', encoding='utf-8')        handler.setFormatter(            logging.Formatter('%(asctime)s [%(levelname)s] %(message)s')        )        logger.addHandler(handler)        logger.setLevel(logging.INFO)    return loggerdef _run(cmd: list[str], cwd: Path, log: logging.Logger) -> None:    log.info('执行: %s', ' '.join(cmd))    proc = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)    if proc.returncode != 0:        raise RuntimeError(            f'命令失败 (exit={proc.returncode}): {" ".join(cmd)}\n'            f'{(proc.stderr or proc.stdout).strip()}'        )def _reorder_crt(path: Path, log: logging.Logger) -> None:    """将 crt 中最后一段 Bag Attributes 直到文件末尾的内容移动到文件开头。"""    text = path.read_text(encoding='utf-8', errors='replace')    idx = text.rfind('Bag Attributes')    if idx > 0:        head, tail = text[:idx], text[idx:]        path.write_text(tail + head, encoding='utf-8')        log.info('已重排 %s（末段 Bag Attributes 移至文件开头）', path)def run_convert(cfg: dict, rule_name: str, root: Path) -> Path:    """执行转换操作；失败时写入 ./logs/convert.log 并以非零码退出。"""    log = _get_logger(root)    try:        matches = resolve_pattern(cfg['from'], root)        if not matches:            raise FileNotFoundError(f"convert.from 没有匹配到文件: {cfg['from']}")        src = matches[0]        output_base = Path(cfg['output'])        if not output_base.is_absolute():            output_base = root / output_base        cert_name = src.parent.name if src.parent != root else rule_name        run_dir = (            output_base / cert_name / datetime.now().strftime('%Y%m%d-%H%M%S')        )        run_dir.mkdir(parents=True, exist_ok=True)        pem = run_dir / f'{_BASE_NAME}.pem'        rsa = run_dir / f'{_BASE_NAME}.rsa'        crt = run_dir / f'{_BASE_NAME}.crt'        _run(            ['openssl', 'pkcs12', '-in', str(src), '-nodes',             '-passin', 'pass:', '-out', str(pem)],            root, log,        )        _run(['openssl', 'rsa', '-in', str(pem), '-out', str(rsa)], root, log)        _run(            ['openssl', 'pkcs12', '-in', str(src), '-nodes', '-nokeys',             '-passin', 'pass:', '-out', str(crt)],            root, log,        )        _reorder_crt(crt, log)        log.info('转换成功: %s -> %s', src, run_dir)        print(f'[convert] 成功: {src} -> {run_dir}')        return run_dir    except Exception as e:        log.error('转换失败: %s', e)        print(f'[convert] 失败: {e}', flush=True)        raise SystemExit(1)